a<-commandArgs(TRUE)[1];b<-readRDS(file.path(a,"convergence_irls_20260918/fit.private.rds"));X<-model.matrix(b$formula,b$model);y<-model.response(b$model);p<-plogis(drop(X%*%coef(b)));w<-p*(1-p);I<-crossprod(X,X*w);h<-rowSums((X%*%solve(I))*X)*w;u<-drop(crossprod(X,y-p+h*(0.5-p)));cat("independently_recomputed_max_adjusted_score",max(abs(u)),"\n");saveRDS(list(max_score=max(abs(u)),score=u),file.path(a,"convergence_irls_20260918/score_check.private.rds"))
